const DP = ['', '', '▙▄▄▟██▄▖']
const TOP = ['███', '▄█▄', '▗▄▖', ' ▖ ', '   ']
const BOT = ['   ', ' ▄ ', '▗█▖', '▟█▙', '███']
const POT = ' ▜███▛ '
const STAGES = [['', '', '   ▖'], ['', '', '   ▌'], ['', '   ▌', '  ▚▌'], ['', '   ▌▞', '  ▚▌'], ['   ▖', '  ▚▌▞', '  ▚▌'], ['  ▟█▙', '  ▚▌▞', '  ▚▌']]
