const dog = (t: boolean, e: boolean) => F(11, S([`${t ? '▖' : ' '}     ▄▄▄ `, `${t ? ' ' : '▝'}▄▄▄▄▄${e ? '█▄█' : '█ █'}▙`, ' ██████▀▀ ', ' ▌▐  ▌▐   ']))
