const ripple = (i: number) => range(22, x => '▁▂▃▂'[(x + i) % 4]).join('')
const hourglass = (s: number) => F(7, S(['▀▀▀▀▀▀▀', ` ▚${TOP[s]}▞ `, ` ▞${BOT[s]}▚ `, '▄▄▄▄▄▄▄']))
const sine = (x: number) => Math.round(3.5 + 3.5 * Math.sin(x * 0.55))

