  hourglass: { ms: 160, frames: [...range(5, s => rep(hourglass(s), 4)).flat(), ...rep(F(7, S(['', '█▙▄▄▄▟█', '█▛▀▀▀▜█'])), 2)] },
  plant: { ms: 200, frames: [
